    "assumptions": [],
}

try:
    metrics = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metrics:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

try:
    seg_cols = ['segment', 'region']
    for sc in seg_cols:
        for mc in metrics:
            top = df[sc].value_counts().head(10).index
            sub = df[df[sc].isin(top)]
            agg = sub.groupby(sc)[mc].mean()
            result['segments'].append({
                'segment_column': sc, 'metric_column': mc,
                'aggregation': 'mean',
                'results': [{'name': str(k), 'value': float(v)} for k, v in agg.items()]
            })
    for mc in metrics:
        agg = df.groupby(['segment', 'region'])[mc].mean()
        result['segments'].append({
            'segment_column': 'segment|region', 'metric_column': mc,
            'aggregation': 'mean',
            'results': [{'name': f'{a}|{b}', 'value': float(v)} for (a, b), v in agg.items()]
        })
except Exception:
    pass

try:
    num_df = df[metrics].dropna()
    for i, c1 in enumerate(metrics):
        for c2 in metrics[i+1:]:
            r = float(num_df[c1].corr(num_df[c2]))
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(r, 4)
except Exception:
    pass

try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
        q1, q3 = float(vals.quantile(0.25)), float(vals.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        frac = mask.sum() / len(vals)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed; IQR boundary exceeded by >5% of values',
                'severity': 'low',
                'explanation': f'Column {col} is heavy-tailed; anomaly flagging skipped'
            })
            continue
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        flagged = vals[mask]
        for idx in flagged.index[:25]:
            raw_val = float(s.loc[idx])
            tv = float(vals.loc[idx])
            if tv < lo5 or tv > hi5:
                sev = 'critical'
            elif tv < lo4 or tv > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            er = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': er, 'severity': sev,
                'explanation': f'Value {raw_val} in column {col} lies outside expected range {er}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
except Exception:
    pass

