try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min()) + 1
            xs = np.log1p(s + shift)
        else:
            xs = s.copy()
            shift = 0
        q1, q3 = xs.quantile(0.25), xs.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (xs < lo3) | (xs > hi3)
        frac = mask.sum() / len(xs)
        if frac > 0.05:
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{orig_lo:.3g} to {orig_hi:.3g}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-boundary flagging skipped'
            })
            continue
        flagged_idx = xs[mask].index
        for idx in flagged_idx:
            xv = xs[idx]
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
            raw_val = float(df.loc[idx, col])
            if xv < lo5 or xv > hi5:
                sev = 'critical'
            elif xv < lo4 or xv > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            er = f'{orig_lo:.3g} to {orig_hi:.3g}'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': er, 'severity': sev,
                'explanation': f'{col} value {raw_val} lies outside expected range {er}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
except Exception:
    pass

