try:
    import numpy as np
    num_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    anomaly_records = []
    for col in num_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_t = np.log1p(s + shift)
        else:
            shift = 0.0
            s_t = s.copy()
        q1 = float(s_t.quantile(0.25))
        q3 = float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = lo3, hi3
        if frac > 0.05:
            anomaly_records.append({
                'column': col,
                'row_index': None,
                'value': None,
                'expected_range': f'{orig_lo:.4f} to {orig_hi:.4f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; more than 5% of values fall outside the extreme IQR boundary of {orig_lo:.4f} to {orig_hi:.4f}'
            })
            continue
        for idx in s_t[mask].index.tolist():
            if len(anomaly_records) >= 25:
                break
            val_t = float(s_t.loc[idx])
            orig_val = float(s.loc[idx])
            if val_t > hi5 or val_t < lo5:
                sev = 'critical'
            elif val_t > hi4 or val_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col,
                'row_index': int(idx),
                'value': orig_val,
                'expected_range': f'{orig_lo:.4f} to {orig_hi:.4f}',
                'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {orig_lo:.4f} to {orig_hi:.4f}'
            })
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

try:
    import numpy as np
    from scipy import stats as sp_stats
    num_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    # sum-based MoM for revenue, units, marketing_spend; mean for discount (rate)
    sum_cols = ['revenue', 'units', 'marketing_spend']
    mean_cols = ['discount']
    monthly_sum = df.groupby('_ym')[sum_cols].sum()
    monthly_mean = df.groupby('_ym')[mean_cols].mean()
    for col in sum_cols:
        vals = monthly_sum[col]
        if len(vals) < 2:
            continue
        prev, last = float(vals.iloc[-2]), float(vals.iloc[-1])
        pct = float((last - prev) / prev * 100) if prev != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': col, 'period': 'MoM',
            'direction': direction, 'pct_change': round(pct, 4), 'segment': None
        })
    for col in mean_cols:
        vals = monthly_mean[col]
        if len(vals) < 2:
            continue
        prev, last = float(vals.iloc[-2]), float(vals.iloc[-1])
        pct = float((last - prev) / prev * 100) if prev != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': col, 'period': 'MoM',
            'direction': direction, 'pct_change': round(pct, 4), 'segment': None
        })
    # Linear trend test + forecast on monthly revenue
    monthly_rev = df.groupby('_ym')['revenue'].sum().reset_index()
    monthly_rev['_t'] = range(len(monthly_rev))
    if len(monthly_rev) >= 3:
        slope, intercept, r_val, p_val, _ = sp_stats.linregress(
            monthly_rev['_t'].values, monthly_rev['revenue'].values)
        next_t = int(len(monthly_rev))
        next_period = str(monthly_rev['_ym'].iloc[-1] + 1)
        forecast_val = round(float(intercept + slope * next_t), 2)
        result['forecast_points'].append({'period': next_period, 'value': forecast_val})
        result['statistical_tests'].append({
            'test_name': 'OLS linear trend — monthly revenue',
            'statistic': round(float(slope), 4),
            'p_value': round(float(p_val), 4),
            'interpretation': (
                f'slope={slope:.4f}, r={r_val:.3f}, p={p_val:.3g}; '
                + ('significant linear trend detected' if p_val < 0.05
                   else 'no significant linear trend')
            )
        })
except Exception:
    pass

