try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    for col in num_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        mask = (s_t < lo) | (s_t > hi)
        if mask.sum() / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged = df.loc[s_t[mask].index, col]
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo) - shift)
            orig_hi = float(np.expm1(hi) - shift)
        else:
            orig_lo, orig_hi = float(lo), float(hi)
        exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        for idx, val in flagged.items():
            tv = s_t.loc[idx]
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(val):.4g} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
except Exception:
    pass

