    monthly_rev = df.groupby('_ym')['revenue'].sum().sort_index()
    if len(monthly_rev) >= 3:
        x = np.arange(len(monthly_rev))
        y = monthly_rev.values.astype(float)
        coeffs = np.polyfit(x, y, 1)
        next_idx = len(monthly_rev)
